        { g: 'προβλεψαμένου', l: 'προβλέπομαι', p: 'فعل، اسم فاعل، أوريست، مفرد مذكر، حالة الجر', t: 'سبق فنظر', d: 'دبّر مسبقاً. لا تأتي إلا هنا في العهد الجديد.' },
        { g: 'τελειωθῶσιν', l: 'τελειόω', p: 'فعل، أوريست مبني للمجهول، صيغة الاحتمال، غائب جمع', t: 'يكملوا', d: 'يصلوا إلى الكمال النهائي.' }
